"""Migration of legacy ACCT_MASTER rows to modern account records."""


def _value(row: dict, key: str) -> str:
    return row.get(key, "")


def _to_float(value: str) -> float:
    return 0.0 if value == "" else float(value)


def _to_date(value: str) -> str | None:
    if value == "" or value == "00000000":
        return None
    return f"{value[:4]}-{value[4:6]}-{value[6:8]}"


def convert_account(row: dict) -> dict | None:
    """Convert one legacy ACCT_MASTER row into an account record."""
    if _value(row, "DEL_FLG") == "Y":
        return None

    return {
        "account_id": _value(row, "ACCT_ID"),
        "name": _value(row, "ACCT_NM"),
        "account_type": _value(row, "ACCT_TYP"),
        "sic_code": _value(row, "SIC_CD"),
        "region": _value(row, "REGION_CD"),
        "annual_revenue": _to_float(_value(row, "ANN_REV")),
        "currency": _value(row, "CURR_CD") or "USD",
        "owner_id": _value(row, "OWNER_UID"),
        "team_code": _value(row, "TEAM_CD"),
        "credit_limit": _to_float(_value(row, "CRED_LIMIT")),
        "credit_hold": _value(row, "CRED_HOLD") == "Y",
        "created_date": _to_date(_value(row, "CREATE_DT")),
        "updated_date": _to_date(_value(row, "UPD_DT")),
    }
